 static long count(List<Item>x,CanonicalCompositionMarginClassifier.Band b){return x.stream().filter(i->i.band==b).count();}static long countFlip(List<Item>x,CanonicalCompositionMarginClassifier.Band b){return x.stream().filter(i->i.flip&&i.band==b).count();}static long mech(List<Item>x,String m){return x.stream().filter(i->i.mechanism.equals(m)).count();}static long samples(Key k,CanonicalCompositionMarginClassifier.Band b){return b==CanonicalCompositionMarginClassifier.Band.CLOSE?k.close:b==CanonicalCompositionMarginClassifier.Band.MEDIUM?k.medium:k.high;}static long flips(Key k,CanonicalCompositionMarginClassifier.Band b){return b==CanonicalCompositionMarginClassifier.Band.CLOSE?k.closeFlips:b==CanonicalCompositionMarginClassifier.Band.MEDIUM?k.mediumFlips:k.highFlips;}static String cohort(Item i){return i.flip?"CHANGED_"+i.band.name():"UNCHANGED";}static String decision(double x,double a,double b){return x<=a?"NEAR":x>=b?"FAR":"MID";}static double q(List<Double>a,double p){List<Double>x=a.stream().filter(Double::isFinite).sorted().toList();return x.isEmpty()?Double.NaN:x.get(Math.max(0,(int)Math.ceil(x.size()*p)-1));}static double min(List<Double>x){return x.stream().mapToDouble(v->v).min().orElse(Double.NaN);}static double max(List<Double>x){return x.stream().mapToDouble(v->v).max().orElse(Double.NaN);}static double rate(long n,long d){return d==0?0:(double)n/d;}static String f(double x){return Double.isFinite(x)?String.format(Locale.ROOT,"%.12f",x):"NOT_APPLICABLE";}static String fmt(double x){return f(x);}static void add(List<List<String>>o,String n,boolean p,long c){o.add(List.of(n,String.valueOf(p),""+c));}
 static String id(Row r){return r.s("caseIndex")+"|"+r.s("attemptId");}static String devKey(Row r){return r.s("context")+"|"+r.s("actionType")+"|"+r.s("scoreDomain");}static double num(Row r,String k){return Double.parseDouble(r.s(k));}static boolean bool(Row r,String k){return Boolean.parseBoolean(r.s(k));}
 static List<Row>read(Path p)throws IOException{List<String>x=Files.readAllLines(p,StandardCharsets.UTF_8),h=csv(x.getFirst());List<Row>o=new ArrayList<>();for(String l:x.subList(1,x.size()))if(!l.isBlank()){List<String>v=csv(l);Map<String,String>m=new HashMap<>();for(int i=0;i<h.size();i++)m.put(h.get(i),i<v.size()?v.get(i):"");o.add(new Row(m));}return o;}static List<String>csv(String l){List<String>o=new ArrayList<>();StringBuilder s=new StringBuilder();boolean q=false;for(int i=0;i<l.length();i++){char c=l.charAt(i);if(c=='"'){if(q&&i+1<l.length()&&l.charAt(i+1)=='"'){s.append('"');i++;}else q=!q;}else if(c==','&&!q){o.add(s.toString());s.setLength(0);}else s.append(c);}o.add(s.toString());return o;}static List<List<String>>rows(String...x){return new ArrayList<>(List.of(List.of(x)));}static void file(String n,List<List<String>>r)throws IOException{StringBuilder s=new StringBuilder();for(List<String>x:r){for(int i=0;i<x.size();i++){if(i>0)s.append(',');String v=x.get(i);if(v.contains(",")||v.contains("\"")||v.contains("\n"))s.append('"').append(v.replace("\"","\"\"")).append('"');else s.append(v);}s.append('\n');}Files.writeString(OUT.resolve(n),s,StandardCharsets.UTF_8);}static String sha(Path p)throws IOException{try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(p)));}catch(Exception e){throw new IllegalStateException(e);}}static Map<Path,String>hashes()throws IOException{LinkedHashMap<Path,String>m=new LinkedHashMap<>();for(Path p:SOURCES)m.put(p,sha(p));return Map.copyOf(m);}static void verifyHashes()throws IOException{if(!sha(SOURCES.get(0)).equals(DSH)||!sha(SOURCES.get(1)).equals(DAH)||!sha(SOURCES.get(3)).equals(HSH)||!sha(SOURCES.get(4)).equals(HAH)||!sha(SOURCES.get(8)).equals(C2SH)||!sha(SOURCES.get(9)).equals(C2AH))throw new IllegalStateException("source hash mismatch");}
 record Row(Map<String,String>v){String s(String k){if(!v.containsKey(k))throw new IllegalArgumentException("missing "+k);return v.get(k);}}record Item(String id,String key,double gap,CanonicalCompositionMarginClassifier.Band band,boolean flip,boolean scoreFlip,String mechanism,double randomMargin,double probabilityDelta,int time,String decisionType){}record Key(String key,long total,long close,long medium,long high,long flips,long closeFlips,long mediumFlips,long highFlips,long scoreDirection,long probabilityCross,long partialGrade,long unresolved,List<String>causes,String primary,String rec){}record Result(List<Item>items,List<Key>keys,Map<Path,String>before,Map<Path,String>after,long duplicates,long foreign,long unknown,long nan,long infinity,long missing,long classificationMismatch,long bandCross,long flipCross,long errors,String verdict,String next){}record Validation(String suites,String tests,String failures,String errors,String skipped,String successful,String fullRuns){static Validation pending(){return new Validation("PENDING_FINAL_REGRESSION","PENDING_FINAL_REGRESSION","PENDING_FINAL_REGRESSION","PENDING_FINAL_REGRESSION","PENDING_FINAL_REGRESSION","PENDING_FINAL_REGRESSION","PENDING_FINAL_REGRESSION");}static Validation finalRun(String[]a){int f=Integer.parseInt(a[2]),e=Integer.parseInt(a[3]);return new Validation(a[0],a[1],a[2],a[3],a[4],String.valueOf(f==0&&e==0),"1");}}
